    # and vertical run meeting at a corner.
    colors = {v for row in grid for v in row if v}
    choice = None
    for color in colors:
        for r in range(h):
            for c in range(w):
                if grid[r][c] != color:
                    continue
                left = sum(1 for x in range(c, -1, -1) if grid[r][x] == color)
                right = sum(1 for x in range(c, w) if grid[r][x] == color)
                up = sum(1 for y in range(r, -1, -1) if grid[y][c] == color)
                down = sum(1 for y in range(r, h) if grid[y][c] == color)
                horizontal = max(left, right)
                vertical = max(up, down)
                if horizontal >= 4 and vertical >= 4:
                    score = horizontal + vertical
                    if choice is None or score > choice[0]:
                        choice = (score, color, r, c)
    if choice is None:
        return out

    _, marker, cr, cc = choice
    # Recolor the small, separate object closest to the L's corner.
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if not color or color == marker or (r, c) in seen:
